"""The PR summary (Phase 10 spec section 5): plain text built from plain facts. No AI, no database.

AS400 picture: the cover sheet stapled to a promotion request. `build_summary` only formats facts
that `gather_summary_facts` (db_tbl_da_handoff.py) collected, so it is tested with made-up facts.
The text never names a test file or a folder path (decision 10).
"""

from pydantic_classes.da_handoff_models import SummaryFacts

DOT = " · "
FOOTER = (
    "Generated by the CodeVision Developer Assistant. "
    "It did not commit, push, approve or open this PR."
)
KIND_TEXT = {"new": "new", "enhance": "enhancement", "fix": "fix"}
SEE_CATALOG = "see the capability catalog"


def build_summary(facts: SummaryFacts, max_chars: int) -> str:
    """Lines 1 to 13 of section 5, in order. Over `max_chars`, the per-criterion lines are cut to
    a count and a note; every other line is kept."""
    text = _join(facts, per_criterion=True)
    if len(text) > max_chars:
        text = _join(facts, per_criterion=False)
    return text


def _join(facts: SummaryFacts, per_criterion: bool) -> str:
    lines = [_title(facts), _kind(facts)]
    if facts.follows_request_id:
        lines.append(f"Follows: {facts.follows_request_id}")
    lines += _criteria(facts, per_criterion)
    if facts.no_negative_reason:
        lines.append(f"No negative scenario: {facts.no_negative_reason}")
    lines.append(_tester(facts))
    lines += _files(facts)
    lines += _list("Reuses", facts.reuses)
    lines += _list("Decisions", facts.decisions)
    lines += _list("Accepted risks", facts.accepted_risks)
    lines += _zones(facts)
    lines += _gaps(facts)
    lines += _list("Senior involvement", facts.senior_involvement)
    lines.append(_final_check(facts))
    lines.append(FOOTER)
    return "\n".join(lines)


def _title(facts: SummaryFacts) -> str:
    return f"{facts.request_id} v{facts.record_version}: {facts.summary}"


def _kind(facts: SummaryFacts) -> str:
    line = f"Kind: {KIND_TEXT[facts.kind]}"
    if facts.kind != "enhance" or not facts.capability:
        return line
    if facts.capability_confirmed:
        senior = f" (senior: {facts.named_senior})" if facts.named_senior else ""
        return f"{line}\nCapability: {facts.capability}{senior}"
    # Still in the Unassigned queue: Admin has not confirmed the pick.
    return (
        f"{line}\nCapability: {facts.capability} "
        "(picked by developer, not yet confirmed by Admin)"
    )


def _criteria(facts: SummaryFacts, per_criterion: bool) -> list[str]:
    total = sum(item.tests for item in facts.criteria)
    passed = sum(item.passed for item in facts.criteria)
    head = (
        f"Criteria: {len(facts.criteria)}{DOT}Tests: {passed} of {total} passed "
        f"({facts.yours} written by the developer, {facts.safety_net} safety-net)"
    )
    if per_criterion:
        return [head] + [
            f"{item.criterion_id}: {_plural(item.tests, 'test')}, "
            + ("passed" if item.tests and item.passed == item.tests else "not all passed")
            for item in facts.criteria
        ]
    note = f"({len(facts.criteria)} criteria: per-criterion lines left out to keep this short)"
    return [head, note]


def _tester(facts: SummaryFacts) -> str:
    parts = [
        f"{facts.must_fixed} Must fix fixed",
        f"{facts.should_fixed} Should fix fixed",
        f"{facts.accepted} accepted",
        f"{facts.fyi} FYI",
    ]
    if facts.overruled:
        by = f" by {facts.overruled_by}" if facts.overruled_by else ""
        parts.append(f"{facts.overruled} overruled{by}")
    return f"Tester: {facts.tester_label} ({', '.join(parts)})"


def _files(facts: SummaryFacts) -> list[str]:
    lines = ["Files:"]
    for item in facts.files:
        edited = ", edited by developer" if item.hand_edited else ""
        lines.append(f"- {item.path} ({'new' if item.is_new else 'changed'}{edited})")
    return lines


def _zones(facts: SummaryFacts) -> list[str]:
    if not facts.zones:
        return ["Flag-for-review zones: none"]
    reviewer = facts.named_senior or SEE_CATALOG
    return ["Flag-for-review zones:"] + [
        f"- {zone} (required reviewer: {reviewer})" for zone in facts.zones
    ]


def _gaps(facts: SummaryFacts) -> list[str]:
    if facts.kind != "enhance":
        return ["Safety-net gaps: not applicable (new code)"]
    lines = _list("Safety-net gaps", [f"{gap}. Check manually" for gap in facts.gaps])
    if facts.impact_unchecked:
        lines.append("Impact could not be checked")
    return lines


def _final_check(facts: SummaryFacts) -> str:
    date = f", {facts.checked_on}" if facts.checked_on else ""
    return f"Final check: workspace = last tested (build {facts.build_number}{date})"


def _list(label: str, items: list[str]) -> list[str]:
    if not items:
        return [f"{label}: none"]
    return [f"{label}:"] + [f"- {item}" for item in items]


def _plural(count: int, word: str) -> str:
    return f"{count} {word}" + ("" if count == 1 else "s")
